diff --git a/scripts/publish-report.js b/scripts/publish-report.js
+import { mkdirSync, rmSync } from 'node:fs';
+
+export function prepareOutput(outputDir) {
+  rmSync(outputDir, { recursive: true, force: true });
+  mkdirSync(outputDir, { recursive: true });
+}
diff --git a/test/publish-report.test.js b/test/publish-report.test.js
+test('creates the output directory', () => {
+  prepareOutput(outputDir);
+  assert.equal(existsSync(outputDir), true);
+});
